// Runnable demo: JSON deserialize with trusted packages + pause/resume on DB health.
package com.bank.settlement.demo;

import java.math.BigDecimal;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class JsonPauseResumeDemo {

    private static final Logger log = Logger.getLogger("JsonKafka");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        JsonValueDeserializer deser = new JsonValueDeserializer("com.bank.settlement.model");
        DatabaseHealth db = new DatabaseHealth();
        SettlementListener listener = new SettlementListener(db);
        ListenerControl control = new ListenerControl(listener);

        // JSON payloads as they arrive on the wire (bytes shown as strings).
        List<String> wire = List.of(
            "{\"txnId\":\"TXN-1\",\"accountId\":\"SAV2001\",\"amount\":20000}",
            "{\"txnId\":\"TXN-2\",\"accountId\":\"CUR3001\",\"amount\":50000}",
            "{\"txnId\":\"TXN-3\",\"accountId\":\"SAV2001\",\"amount\":30000}",
            "{\"txnId\":\"TXN-4\",\"accountId\":\"CUR3001\",\"amount\":60000}"
        );

        log.info("=== DB up: consume TXN-1, TXN-2 normally ===");
        control.deliver(deser.deserialize(wire.get(0)));
        control.deliver(deser.deserialize(wire.get(1)));

        log.info("=== DB goes DOWN: health watcher pauses the listener ===");
        db.setUp(false);
        control.onHealthChange(db);   // pause()
        control.deliver(deser.deserialize(wire.get(2)));  // buffered, not processed
        control.deliver(deser.deserialize(wire.get(3)));  // buffered, not processed

        log.info("=== DB back UP: health watcher resumes, held events flush in order ===");
        db.setUp(true);
        control.onHealthChange(db);   // resume() + drain buffer
    }
}

// ─── Would be in TxnEvent.java ───
class TxnEvent {
    String txnId;
    String accountId;
    BigDecimal amount;
    TxnEvent() { }   // Jackson needs a no-arg constructor
    TxnEvent(String txnId, String accountId, BigDecimal amount) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.amount = amount;
    }
}

// ─── Would be in JsonValueDeserializer.java ───
// Models JsonDeserializer + trusted-packages enforcement (tiny hand parser).
class JsonValueDeserializer {
    private static final Logger log = Logger.getLogger("JsonKafka");
    private final String trustedPackage;
    JsonValueDeserializer(String trustedPackage) { this.trustedPackage = trustedPackage; }

    TxnEvent deserialize(String json) {
        // Real JsonDeserializer checks a type header against trusted packages.
        // Here the target type is com.bank.settlement.model.TxnEvent (trusted).
        String targetType = "com.bank.settlement.model.TxnEvent";
        if (!targetType.startsWith(trustedPackage)) {
            throw new SecurityException("untrusted type rejected: " + targetType);
        }
        TxnEvent e = new TxnEvent();
        e.txnId = field(json, "txnId");
        e.accountId = field(json, "accountId");
        e.amount = new BigDecimal(field(json, "amount"));
        log.fine(() -> "deserialized JSON into TxnEvent txn=" + e.txnId);
        return e;
    }
    private String field(String json, String key) {
        int i = json.indexOf("\"" + key + "\"");
        int colon = json.indexOf(':', i);
        int start = colon + 1;
        while (json.charAt(start) == ' ' || json.charAt(start) == '"') start++;
        int end = start;
        while (end < json.length() && "\",}".indexOf(json.charAt(end)) < 0) end++;
        return json.substring(start, end);
    }
}

