class DatabaseHealth {
    private volatile boolean up = true;
    boolean isUp() { return up; }
    void setUp(boolean up) { this.up = up; }
}

// ─── Would be in SettlementListener.java ───
class SettlementListener {
    private static final Logger log = Logger.getLogger("JsonKafka");
    private final DatabaseHealth db;
    SettlementListener(DatabaseHealth db) { this.db = db; }

    void onTxn(TxnEvent e) {
        if (!db.isUp()) throw new IllegalStateException("DB down; cannot settle " + e.txnId);
        log.info(() -> "settled txn=" + e.txnId + " account=" + e.accountId
                + " amount=Rs." + e.amount);
    }
}

// ─── Would be in ListenerControl.java ───
// Models KafkaListenerEndpointRegistry + MessageListenerContainer pause/resume.
class ListenerControl {
    private static final Logger log = Logger.getLogger("JsonKafka");
    private final SettlementListener listener;
    private boolean paused = false;
    private final Deque<TxnEvent> buffer = new ArrayDeque<>();  // held while paused

    ListenerControl(SettlementListener listener) { this.listener = listener; }

    void deliver(TxnEvent e) {
        if (paused) {
            buffer.addLast(e);  // offsets not advanced; record held back
            log.warning(() -> "listener PAUSED; holding txn=" + e.txnId);
            return;
        }
        listener.onTxn(e);
    }

    void onHealthChange(DatabaseHealth db) {
        if (!db.isUp() && !paused) {
            paused = true;
            log.severe("DB down -> container.pause() (offsets frozen, no rebalance)");
        } else if (db.isUp() && paused) {
            paused = false;
            log.info("DB up -> container.resume(); draining held events in order");
            while (!buffer.isEmpty()) listener.onTxn(buffer.pollFirst());
        }
    }
}

